      "Partner Terms of Cooperation": "Condiciones de colaboración para socios",
      "Ride24 operates as an online marketplace platform.": "Ride24 funciona como una plataforma de intermediación en línea.",
      "§1 Platform Nature": "§1 Naturaleza de la plataforma",
      "Ride24 operates as an online marketplace platform that enables customers to search for and reserve vehicle rental services offered by independent rental companies (“Partners”).": "Ride24 funciona como una plataforma de intermediación en línea que permite a los clientes buscar y reservar servicios de alquiler de vehículos ofrecidos por empresas de alquiler independientes («Socios»).",
      "Ride24 does not provide vehicle rental services and is not a party to the rental agreement.": "Ride24 no presta servicios de alquiler de vehículos ni es parte del contrato de alquiler.",
      "The rental agreement is concluded directly between the customer and the Partner.": "El contrato de alquiler se celebra directamente entre el cliente y el Socio.",
      "§2 Partner Account": "§2 Cuenta de socio",
      "Ride24 provides the Partner with access to a Partner Account on the Ride24 platform. The Partner is responsible for:": "Ride24 proporciona al Socio acceso a una cuenta de socio en la plataforma Ride24. El Socio es responsable de:",
      "maintaining accurate information about vehicles": "mantener información precisa sobre los vehículos",
      "updating prices and availability": "actualizar precios y disponibilidad",
      "uploading vehicle descriptions and photos": "subir descripciones y fotografías de los vehículos",
      "maintaining valid rental terms and policies": "mantener condiciones y normas de alquiler vigentes",
      "The Partner guarantees that all information published on the platform is accurate and lawful.": "El Socio garantiza que toda la información publicada en la plataforma es precisa y conforme a la ley.",
      "§3 Vehicle Offers": "§3 Ofertas de vehículos",
      "The Partner may publish vehicle rental offers through the Ride24 Partner Panel. Each offer must include:": "El Socio puede publicar ofertas de alquiler de vehículos a través del panel de socios de Ride24. Cada oferta debe incluir:",
      "vehicle class and price list": "categoría del vehículo y lista de precios",
      "rental conditions": "condiciones de alquiler",
      "pickup location": "lugar de recogida",
      "required documents": "documentos necesarios",
      "§4 Reservation Process": "§4 Proceso de reserva",
      "Customers may create reservations through the Ride24 platform. After a reservation request is submitted, the Partner receives a reservation notification containing: reservation details, vehicle type, and customer contact data.": "Los clientes pueden realizar reservas a través de Ride24. Tras enviar una solicitud, el Socio recibe una notificación con los detalles de la reserva, el tipo de vehículo y los datos de contacto del cliente.",
      "The Partner must confirm or reject the reservation within 24 hours. Failure to respond within the required time may result in automatic cancellation of the reservation.": "El Socio debe confirmar o rechazar la reserva en un plazo de 24 horas. La falta de respuesta dentro del plazo puede dar lugar a la cancelación automática de la reserva.",
      "§5 Reservation Confirmation": "§5 Confirmación de la reserva",
      "Once the Partner confirms the reservation: the system generates a Ride24 Voucher and the customer receives the voucher electronically.": "Cuando el Socio confirma la reserva, el sistema genera un voucher de Ride24 y el cliente lo recibe por vía electrónica.",
      "The Partner agrees to honor all confirmed vouchers issued through the Ride24 platform.": "El Socio se compromete a respetar todos los vouchers confirmados emitidos a través de Ride24.",
      "§6 Partner Commission / Discount": "§6 Comisión / descuento del Socio",
      "The Partner grants Ride24 a permanent commission or discount calculated from the standard rental prices listed in the Partner account.": "El Socio concede a Ride24 una comisión o descuento permanente calculado sobre los precios estándar de alquiler indicados en su cuenta.",
      "§7 Partner Responsibilities": "§7 Responsabilidades del Socio",
      "The Partner is fully responsible for: the condition of the vehicles, the execution of the rental service, insurance coverage, and compliance with applicable laws.": "El Socio es plenamente responsable del estado de los vehículos, la prestación del servicio de alquiler, la cobertura del seguro y el cumplimiento de las leyes aplicables.",
      "Ride24 is not responsible for the performance of rental services by the Partner.": "Ride24 no es responsable de la prestación de los servicios de alquiler por parte del Socio.",
      "§8 Customer Data Protection": "§8 Protección de datos del cliente",
      "The Partner may receive customer personal data through the Ride24 platform. The Partner agrees to:": "El Socio puede recibir datos personales de los clientes a través de Ride24. El Socio se compromete a:",
      "use the data only for reservation fulfillment": "utilizar los datos únicamente para gestionar la reserva",
      "comply with GDPR regulations": "cumplir el RGPD",
      "§9 Reservation Documents": "§9 Documentos de la reserva",
      "Customers receive access to reservation documents through their Ride24 account. Documents may include: reservation confirmation, voucher, partner rental conditions, and partner rental rules.": "Los clientes acceden a los documentos de la reserva desde su cuenta Ride24. Pueden incluir la confirmación de reserva, el voucher, las condiciones y las normas de alquiler del Socio.",
      "§10 Account Deactivation and Data Deletion": "§10 Desactivación de la cuenta y eliminación de datos",
      "The Partner has the right to deactivate their account at any time via the panel. Upon deactivation, the Partner's offers will be immediately hidden from search results. Account data will be permanently deleted from the platform after 30 days, except for data strictly required for billing and tax purposes.": "El Socio puede desactivar su cuenta en cualquier momento desde el panel. Sus ofertas se ocultarán inmediatamente en la búsqueda. Los datos de la cuenta se eliminarán permanentemente después de 30 días, salvo los estrictamente necesarios para fines contables y fiscales.",
      "I understand": "Entendido",
      "Add location": "Añadir ubicación",
      "⚠️ IMPORTANT: Enter names in English ONLY!": "⚠️ IMPORTANTE: ¡Introduce los nombres SOLO en inglés!",
      "For the system to link locations with the search engine, type e.g., 'Greece' instead of 'Grecja', 'Rhodes' instead of 'Rodos'.": "Para vincular las ubicaciones con el buscador, escribe, por ejemplo, 'Greece' en lugar de 'Grecia', 'Rhodes' en lugar de 'Rodas'.",
