      "Applies to all your locations. A value of 1 means no extra restriction. Customers will see a notice when their selected rental period is too short.": "Ισχύει για όλες τις τοποθεσίες σας. Η τιμή 1 σημαίνει χωρίς πρόσθετο περιορισμό. Ο πελάτης θα δει ενημέρωση αν επιλέξει πολύ σύντομη περίοδο.",
