      "API access is securely managed by the Ride24 administrator. Login details and API keys are not displayed or stored in the partner panel.": "Η πρόσβαση στο API διαχειρίζεται με ασφάλεια από τον διαχειριστή του Ride24. Τα στοιχεία σύνδεσης και τα κλειδιά API δεν εμφανίζονται ούτε αποθηκεύονται στον πίνακα συνεργάτη.",
