      "Cash on pickup, refunded upon return under rental terms; this is not a card hold.": "Καταβάλλεται με μετρητά κατά την παραλαβή και επιστρέφεται κατά την επιστροφή σύμφωνα με τους όρους ενοικίασης. Δεν αποτελεί δέσμευση ποσού σε κάρτα.",
