      "🧑 Driver included": "🧑 Με οδηγό",
      "Check if this vehicle is rented only with a chauffeur. The offer will be displayed as PREMIUM.": "Επιλέξτε το αν το όχημα ενοικιάζεται αποκλειστικά με οδηγό. Η προσφορά θα εμφανίζεται ως PREMIUM.",
