      "Pub. Price": "Δημόσια τιμή",
      "📅 Rental duration discounts (optional)": "📅 Εκπτώσεις διάρκειας ενοικίασης (προαιρετικές)",
      "Set one set of tiers for this vehicle. The discount is automatically applied to the active base or seasonal price. If you add no tiers, your current pricing remains unchanged.": "Ορίστε ένα σύνολο κλιμάκων για αυτό το όχημα. Η έκπτωση εφαρμόζεται αυτόματα στην ισχύουσα βασική ή εποχική τιμή. Αν δεν προσθέσετε κλίμακες, η υπάρχουσα τιμολόγηση παραμένει ίδια.",
