      "Bookings cannot start or end during the blocked hours. No fee is charged.": "Nelle ore bloccate non sono consentiti ritiri o riconsegne. Non viene addebitato alcun supplemento.",
      "What is the fee for?": "Per cosa viene applicato il supplemento?",
