      "Save Password": "Salva password",
      "Partner Terms of Cooperation": "Condizioni di collaborazione per i partner",
      "Ride24 operates as an online marketplace platform.": "Ride24 opera come piattaforma di intermediazione online.",
      "§1 Platform Nature": "§1 Natura della piattaforma",
      "Ride24 operates as an online marketplace platform that enables customers to search for and reserve vehicle rental services offered by independent rental companies (“Partners”).": "Ride24 opera come piattaforma di intermediazione online che consente ai clienti di cercare e prenotare servizi di noleggio di veicoli offerti da società di noleggio indipendenti («Partner»).",
      "Ride24 does not provide vehicle rental services and is not a party to the rental agreement.": "Ride24 non fornisce servizi di noleggio di veicoli e non è parte del contratto di noleggio.",
      "The rental agreement is concluded directly between the customer and the Partner.": "Il contratto di noleggio è stipulato direttamente tra il cliente e il Partner.",
      "§2 Partner Account": "§2 Account partner",
      "Ride24 provides the Partner with access to a Partner Account on the Ride24 platform. The Partner is responsible for:": "Ride24 fornisce al Partner l'accesso a un account partner sulla piattaforma Ride24. Il Partner è responsabile di:",
      "maintaining accurate information about vehicles": "mantenere accurate le informazioni sui veicoli",
      "updating prices and availability": "aggiornare prezzi e disponibilità",
      "uploading vehicle descriptions and photos": "caricare descrizioni e foto dei veicoli",
      "maintaining valid rental terms and policies": "mantenere aggiornati condizioni e regolamenti di noleggio",
      "The Partner guarantees that all information published on the platform is accurate and lawful.": "Il Partner garantisce che tutte le informazioni pubblicate sulla piattaforma siano accurate e conformi alla legge.",
      "§3 Vehicle Offers": "§3 Offerte dei veicoli",
      "The Partner may publish vehicle rental offers through the Ride24 Partner Panel. Each offer must include:": "Il Partner può pubblicare offerte di noleggio attraverso il pannello partner Ride24. Ogni offerta deve includere:",
      "vehicle class and price list": "categoria del veicolo e listino prezzi",
      "rental conditions": "condizioni di noleggio",
      "pickup location": "luogo di ritiro",
      "required documents": "documenti richiesti",
      "§4 Reservation Process": "§4 Procedura di prenotazione",
      "Customers may create reservations through the Ride24 platform. After a reservation request is submitted, the Partner receives a reservation notification containing: reservation details, vehicle type, and customer contact data.": "I clienti possono effettuare prenotazioni tramite Ride24. Dopo l'invio di una richiesta, il Partner riceve una notifica con i dettagli della prenotazione, il tipo di veicolo e i recapiti del cliente.",
      "The Partner must confirm or reject the reservation within 24 hours. Failure to respond within the required time may result in automatic cancellation of the reservation.": "Il Partner deve confermare o rifiutare la prenotazione entro 24 ore. La mancata risposta entro il termine può comportare l'annullamento automatico della prenotazione.",
      "§5 Reservation Confirmation": "§5 Conferma della prenotazione",
      "Once the Partner confirms the reservation: the system generates a Ride24 Voucher and the customer receives the voucher electronically.": "Quando il Partner conferma la prenotazione, il sistema genera un voucher Ride24 che viene inviato al cliente elettronicamente.",
      "The Partner agrees to honor all confirmed vouchers issued through the Ride24 platform.": "Il Partner si impegna a rispettare tutti i voucher confermati emessi tramite Ride24.",
      "§6 Partner Commission / Discount": "§6 Commissione / sconto del Partner",
      "The Partner grants Ride24 a permanent commission or discount calculated from the standard rental prices listed in the Partner account.": "Il Partner riconosce a Ride24 una commissione o uno sconto permanente calcolato sui prezzi standard di noleggio indicati nel proprio account.",
      "§7 Partner Responsibilities": "§7 Responsabilità del Partner",
      "The Partner is fully responsible for: the condition of the vehicles, the execution of the rental service, insurance coverage, and compliance with applicable laws.": "Il Partner è pienamente responsabile delle condizioni dei veicoli, dell'esecuzione del servizio di noleggio, della copertura assicurativa e del rispetto delle leggi applicabili.",
      "Ride24 is not responsible for the performance of rental services by the Partner.": "Ride24 non è responsabile dell'esecuzione dei servizi di noleggio da parte del Partner.",
      "§8 Customer Data Protection": "§8 Protezione dei dati dei clienti",
      "The Partner may receive customer personal data through the Ride24 platform. The Partner agrees to:": "Il Partner può ricevere dati personali dei clienti tramite Ride24. Il Partner si impegna a:",
      "use the data only for reservation fulfillment": "utilizzare i dati solo per l'esecuzione della prenotazione",
      "comply with GDPR regulations": "rispettare il GDPR",
      "§9 Reservation Documents": "§9 Documenti della prenotazione",
      "Customers receive access to reservation documents through their Ride24 account. Documents may include: reservation confirmation, voucher, partner rental conditions, and partner rental rules.": "I clienti accedono ai documenti della prenotazione dal proprio account Ride24. I documenti possono includere conferma, voucher, condizioni e regolamento di noleggio del Partner.",
      "§10 Account Deactivation and Data Deletion": "§10 Disattivazione dell'account ed eliminazione dei dati",
      "The Partner has the right to deactivate their account at any time via the panel. Upon deactivation, the Partner's offers will be immediately hidden from search results. Account data will be permanently deleted from the platform after 30 days, except for data strictly required for billing and tax purposes.": "Il Partner può disattivare l'account in qualsiasi momento dal pannello. Le sue offerte saranno subito nascoste dai risultati di ricerca. I dati dell'account saranno eliminati definitivamente dopo 30 giorni, salvo quelli strettamente necessari per finalità contabili e fiscali.",
      "I understand": "Ho capito",
      "Add location": "Aggiungi località",
      "⚠️ IMPORTANT: Enter names in English ONLY!": "⚠️ IMPORTANTE: inserisci i nomi SOLO in inglese!",
      "For the system to link locations with the search engine, type e.g., 'Greece' instead of 'Grecja', 'Rhodes' instead of 'Rodos'.": "Per collegare le località al motore di ricerca, scrivi ad esempio 'Greece' anziché 'Grecia', 'Rhodes' anziché 'Rodi'.",
