      "Save Password": "Passwort speichern",
      "Partner Terms of Cooperation": "Kooperationsbedingungen für Partner",
      "Ride24 operates as an online marketplace platform.": "Ride24 betreibt einen Online-Marktplatz.",
      "§1 Platform Nature": "§1 Art der Plattform",
      "Ride24 operates as an online marketplace platform that enables customers to search for and reserve vehicle rental services offered by independent rental companies (“Partners”).": "Ride24 betreibt einen Online-Marktplatz, auf dem Kunden Fahrzeugmietleistungen unabhängiger Mietwagenunternehmen („Partner“) suchen und buchen können.",
      "Ride24 does not provide vehicle rental services and is not a party to the rental agreement.": "Ride24 erbringt keine Fahrzeugmietleistungen und ist keine Partei des Mietvertrags.",
      "The rental agreement is concluded directly between the customer and the Partner.": "Der Mietvertrag wird unmittelbar zwischen dem Kunden und dem Partner geschlossen.",
      "§2 Partner Account": "§2 Partnerkonto",
      "Ride24 provides the Partner with access to a Partner Account on the Ride24 platform. The Partner is responsible for:": "Ride24 gewährt dem Partner Zugang zu einem Partnerkonto auf der Ride24-Plattform. Der Partner ist verantwortlich für:",
      "maintaining accurate information about vehicles": "korrekte Fahrzeuginformationen",
      "updating prices and availability": "die Aktualisierung von Preisen und Verfügbarkeit",
      "uploading vehicle descriptions and photos": "das Hochladen von Fahrzeugbeschreibungen und Fotos",
      "maintaining valid rental terms and policies": "gültige Mietbedingungen und Mietregeln",
      "The Partner guarantees that all information published on the platform is accurate and lawful.": "Der Partner gewährleistet, dass alle auf der Plattform veröffentlichten Informationen korrekt und rechtmäßig sind.",
      "§3 Vehicle Offers": "§3 Fahrzeugangebote",
      "The Partner may publish vehicle rental offers through the Ride24 Partner Panel. Each offer must include:": "Der Partner kann Fahrzeugmietangebote über den Ride24-Partnerbereich veröffentlichen. Jedes Angebot muss Folgendes enthalten:",
      "vehicle class and price list": "Fahrzeugklasse und Preisliste",
      "rental conditions": "Mietbedingungen",
      "pickup location": "Abholort",
      "required documents": "erforderliche Dokumente",
      "§4 Reservation Process": "§4 Buchungsablauf",
      "Customers may create reservations through the Ride24 platform. After a reservation request is submitted, the Partner receives a reservation notification containing: reservation details, vehicle type, and customer contact data.": "Kunden können über Ride24 Buchungen vornehmen. Nach dem Absenden einer Buchungsanfrage erhält der Partner eine Benachrichtigung mit Buchungsdetails, Fahrzeugtyp und Kontaktdaten des Kunden.",
      "The Partner must confirm or reject the reservation within 24 hours. Failure to respond within the required time may result in automatic cancellation of the reservation.": "Der Partner muss die Buchung innerhalb von 24 Stunden bestätigen oder ablehnen. Erfolgt keine fristgerechte Antwort, kann die Buchung automatisch storniert werden.",
      "§5 Reservation Confirmation": "§5 Buchungsbestätigung",
      "Once the Partner confirms the reservation: the system generates a Ride24 Voucher and the customer receives the voucher electronically.": "Sobald der Partner die Buchung bestätigt, erstellt das System einen Ride24-Voucher, den der Kunde elektronisch erhält.",
      "The Partner agrees to honor all confirmed vouchers issued through the Ride24 platform.": "Der Partner verpflichtet sich, alle über Ride24 ausgestellten bestätigten Voucher einzulösen.",
      "§6 Partner Commission / Discount": "§6 Partnerprovision / Rabatt",
      "The Partner grants Ride24 a permanent commission or discount calculated from the standard rental prices listed in the Partner account.": "Der Partner gewährt Ride24 eine dauerhafte Provision oder einen Rabatt auf die im Partnerkonto angegebenen regulären Mietpreise.",
      "§7 Partner Responsibilities": "§7 Pflichten des Partners",
      "The Partner is fully responsible for: the condition of the vehicles, the execution of the rental service, insurance coverage, and compliance with applicable laws.": "Der Partner trägt die volle Verantwortung für den Zustand der Fahrzeuge, die Durchführung der Vermietung, den Versicherungsschutz und die Einhaltung der geltenden Gesetze.",
      "Ride24 is not responsible for the performance of rental services by the Partner.": "Ride24 ist nicht für die Erbringung der Mietleistungen durch den Partner verantwortlich.",
      "§8 Customer Data Protection": "§8 Schutz der Kundendaten",
      "The Partner may receive customer personal data through the Ride24 platform. The Partner agrees to:": "Der Partner kann über Ride24 personenbezogene Kundendaten erhalten. Der Partner verpflichtet sich:",
      "use the data only for reservation fulfillment": "die Daten ausschließlich zur Abwicklung der Buchung zu verwenden",
      "comply with GDPR regulations": "die DSGVO einzuhalten",
      "§9 Reservation Documents": "§9 Buchungsunterlagen",
      "Customers receive access to reservation documents through their Ride24 account. Documents may include: reservation confirmation, voucher, partner rental conditions, and partner rental rules.": "Kunden erhalten über ihr Ride24-Konto Zugriff auf ihre Buchungsunterlagen. Dazu können Buchungsbestätigung, Voucher sowie Mietbedingungen und Mietregeln des Partners gehören.",
      "§10 Account Deactivation and Data Deletion": "§10 Kontodeaktivierung und Datenlöschung",
      "The Partner has the right to deactivate their account at any time via the panel. Upon deactivation, the Partner's offers will be immediately hidden from search results. Account data will be permanently deleted from the platform after 30 days, except for data strictly required for billing and tax purposes.": "Der Partner kann sein Konto jederzeit im Partnerbereich deaktivieren. Seine Angebote werden sofort aus den Suchergebnissen ausgeblendet. Die Kontodaten werden nach 30 Tagen dauerhaft gelöscht, ausgenommen Daten, die für Abrechnungs- und Steuerzwecke zwingend erforderlich sind.",
      "I understand": "Verstanden",
      "Add location": "Standort hinzufügen",
      "⚠️ IMPORTANT: Enter names in English ONLY!": "⚠️ WICHTIG: Namen NUR auf Englisch eingeben!",
      "For the system to link locations with the search engine, type e.g., 'Greece' instead of 'Grecja', 'Rhodes' instead of 'Rodos'.": "Damit Standorte mit der Suche verknüpft werden, geben Sie z. B. 'Greece' statt 'Griechenland' und 'Rhodes' statt 'Rhodos' ein.",
