      "🧑 Driver included": "🧑 С водителем",
      "Check if this vehicle is rented only with a chauffeur. The offer will be displayed as PREMIUM.": "Отметьте, если автомобиль сдаётся только с водителем. Предложение будет отображаться как PREMIUM.",
