      "Check if this vehicle is rented only with a chauffeur. The offer will be displayed as PREMIUM.": "Cochez si ce véhicule est loué uniquement avec chauffeur. L'offre sera affichée comme PREMIUM.",
      "Hours per day included": "Heures incluses par jour",
      "Partner commission (%)": "Remise partenaire (%)",
