      "I accept": "J'accepte",
      "B2B Terms of Cooperation": "Conditions de collaboration B2B",
      "Save Password": "Enregistrer le mot de passe",
      "Partner Terms of Cooperation": "Conditions de collaboration des partenaires",
      "Ride24 operates as an online marketplace platform.": "Ride24 est une plateforme de mise en relation en ligne.",
      "§1 Platform Nature": "§1 Nature de la plateforme",
      "Ride24 operates as an online marketplace platform that enables customers to search for and reserve vehicle rental services offered by independent rental companies (“Partners”).": "Ride24 est une plateforme de mise en relation en ligne permettant aux clients de rechercher et de réserver des services de location de véhicules proposés par des sociétés de location indépendantes (« Partenaires »).",
      "Ride24 does not provide vehicle rental services and is not a party to the rental agreement.": "Ride24 ne fournit pas de services de location de véhicules et n'est pas partie au contrat de location.",
      "The rental agreement is concluded directly between the customer and the Partner.": "Le contrat de location est conclu directement entre le client et le Partenaire.",
      "§2 Partner Account": "§2 Compte partenaire",
      "Ride24 provides the Partner with access to a Partner Account on the Ride24 platform. The Partner is responsible for:": "Ride24 donne au Partenaire accès à un compte partenaire sur la plateforme Ride24. Le Partenaire est responsable de :",
      "maintaining accurate information about vehicles": "l'exactitude des informations sur les véhicules",
      "updating prices and availability": "la mise à jour des prix et des disponibilités",
      "uploading vehicle descriptions and photos": "l'importation des descriptions et des photos des véhicules",
      "maintaining valid rental terms and policies": "la mise à disposition de conditions et de règlements de location valides",
      "The Partner guarantees that all information published on the platform is accurate and lawful.": "Le Partenaire garantit que toutes les informations publiées sur la plateforme sont exactes et conformes à la loi.",
      "§3 Vehicle Offers": "§3 Offres de véhicules",
      "The Partner may publish vehicle rental offers through the Ride24 Partner Panel. Each offer must include:": "Le Partenaire peut publier des offres de location de véhicules via l'espace partenaire Ride24. Chaque offre doit comprendre :",
      "vehicle class and price list": "la catégorie du véhicule et la grille tarifaire",
      "rental conditions": "les conditions de location",
      "pickup location": "le lieu de prise en charge",
      "required documents": "les documents requis",
      "§4 Reservation Process": "§4 Processus de réservation",
      "Customers may create reservations through the Ride24 platform. After a reservation request is submitted, the Partner receives a reservation notification containing: reservation details, vehicle type, and customer contact data.": "Les clients peuvent réserver via Ride24. Après l'envoi d'une demande, le Partenaire reçoit une notification contenant les détails de la réservation, le type de véhicule et les coordonnées du client.",
      "The Partner must confirm or reject the reservation within 24 hours. Failure to respond within the required time may result in automatic cancellation of the reservation.": "Le Partenaire doit confirmer ou refuser la réservation dans les 24 heures. L'absence de réponse dans le délai prévu peut entraîner l'annulation automatique de la réservation.",
      "§5 Reservation Confirmation": "§5 Confirmation de réservation",
      "Once the Partner confirms the reservation: the system generates a Ride24 Voucher and the customer receives the voucher electronically.": "Lorsque le Partenaire confirme la réservation, le système génère un voucher Ride24 que le client reçoit par voie électronique.",
      "The Partner agrees to honor all confirmed vouchers issued through the Ride24 platform.": "Le Partenaire s'engage à honorer tous les vouchers confirmés émis via Ride24.",
      "§6 Partner Commission / Discount": "§6 Commission / remise du Partenaire",
      "The Partner grants Ride24 a permanent commission or discount calculated from the standard rental prices listed in the Partner account.": "Le Partenaire accorde à Ride24 une commission ou une remise permanente calculée sur les prix de location standard indiqués dans son compte.",
      "§7 Partner Responsibilities": "§7 Responsabilités du Partenaire",
      "The Partner is fully responsible for: the condition of the vehicles, the execution of the rental service, insurance coverage, and compliance with applicable laws.": "Le Partenaire est pleinement responsable de l'état des véhicules, de l'exécution du service de location, de la couverture d'assurance et du respect de la législation applicable.",
      "Ride24 is not responsible for the performance of rental services by the Partner.": "Ride24 n'est pas responsable de l'exécution des services de location par le Partenaire.",
      "§8 Customer Data Protection": "§8 Protection des données des clients",
      "The Partner may receive customer personal data through the Ride24 platform. The Partner agrees to:": "Le Partenaire peut recevoir des données personnelles des clients via Ride24. Il s'engage à :",
      "use the data only for reservation fulfillment": "utiliser les données uniquement pour l'exécution de la réservation",
      "comply with GDPR regulations": "respecter le RGPD",
      "§9 Reservation Documents": "§9 Documents de réservation",
      "Customers receive access to reservation documents through their Ride24 account. Documents may include: reservation confirmation, voucher, partner rental conditions, and partner rental rules.": "Les clients accèdent aux documents de réservation depuis leur compte Ride24. Ces documents peuvent comprendre la confirmation de réservation, le voucher, les conditions et le règlement de location du Partenaire.",
      "§10 Account Deactivation and Data Deletion": "§10 Désactivation du compte et suppression des données",
      "The Partner has the right to deactivate their account at any time via the panel. Upon deactivation, the Partner's offers will be immediately hidden from search results. Account data will be permanently deleted from the platform after 30 days, except for data strictly required for billing and tax purposes.": "Le Partenaire peut désactiver son compte à tout moment depuis son espace. Ses offres seront immédiatement masquées dans les résultats de recherche. Les données du compte seront supprimées définitivement après 30 jours, à l'exception de celles strictement nécessaires à la facturation et aux obligations fiscales.",
      "I understand": "J'ai compris",
      "Add location": "Ajouter un lieu",
      "⚠️ IMPORTANT: Enter names in English ONLY!": "⚠️ IMPORTANT : saisissez les noms UNIQUEMENT en anglais !",
      "For the system to link locations with the search engine, type e.g., 'Greece' instead of 'Grecja', 'Rhodes' instead of 'Rodos'.": "Pour relier les lieux au moteur de recherche, saisissez par exemple 'Greece' au lieu de 'Grèce', 'Crete' au lieu de 'Crète'.",
